    c.createEl("div", { cls: "er-set-note", text: __ertr("\u0428\u0440\u0438\u0444\u0442, \u0440\u0430\u0437\u043C\u0435\u0440 \u0438 \u043C\u0435\u0436\u0441\u0442\u0440\u043E\u0447\u043D\u044B\u0439 \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u0440\u044F\u043C\u043E \u0432 \u043A\u043D\u0438\u0433\u0435 \u2014 \u0438\u043A\u043E\u043D\u043A\u0430 \u043F\u043E\u043B\u0437\u0443\u043D\u043A\u043E\u0432 \u0432\u0432\u0435\u0440\u0445\u0443 \u0447\u0438\u0442\u0430\u043B\u043A\u0438.") });
