  _tabAbout(c) {
    new import_obsidian.Setting(c).setName("\u042F\u0437\u044B\u043A / Language").setDesc("\u042F\u0437\u044B\u043A \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430 \u043F\u043B\u0430\u0433\u0438\u043D\u0430. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443 \u0437\u0430\u043D\u043E\u0432\u043E, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C. / Plugin interface language. Reopen the book to apply.").addDropdown((d) => d.addOption("ru", "\u0420\u0443\u0441\u0441\u043A\u0438\u0439").addOption("en", "English").setValue(this.plugin.settings.language || "ru").onChange(async (v) => {
      this.plugin.settings.language = v;
      globalThis.__erReaderLang = v;
      await this.plugin.saveAll();
      this._redraw();
    }));
    new import_obsidian.Setting(c).setName(__ertr("\u0418\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u044F \u043F\u043E \u043F\u043B\u0430\u0433\u0438\u043D\u0443")).setDesc(__ertr("21 \u044D\u043A\u0440\u0430\u043D \u0441 \u043E\u0431\u044A\u044F\u0441\u043D\u0435\u043D\u0438\u0435\u043C: \u0444\u043E\u0440\u043C\u0430\u0442\u044B, \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F, \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438, \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u044F, \u0430 \u0437\u0430\u0442\u0435\u043C \u0440\u0430\u0437\u0431\u043E\u0440 \u043A\u0430\u0436\u0434\u043E\u0439 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u2014 \u0447\u0442\u043E \u0434\u0435\u043B\u0430\u0435\u0442, \u0447\u0442\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0438 \u0447\u0442\u043E \u0431\u0443\u0434\u0435\u0442, \u0435\u0441\u043B\u0438 \u043D\u0435 \u0442\u0440\u043E\u0433\u0430\u0442\u044C.")).addButton((b) => b.setButtonText(__ertr("\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u044E")).onClick(() => new OnboardingModal(this.app, this.plugin).open()));
    new import_obsidian.Setting(c).setName(__ertr("\u0427\u0442\u043E \u043D\u043E\u0432\u043E\u0433\u043E")).setDesc(__ertr("\u0421\u043F\u0438\u0441\u043E\u043A \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0445 \u0432\u0435\u0440\u0441\u0438\u0439.")).addButton((b) => b.setButtonText(__ertr("\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C")).onClick(() => {
      new WhatsNewModal(this.app, this.plugin, WHATS_NEW.slice(0, 4)).open();
    }));
    const about = c.createEl("div", { cls: "er-set-note" });
    about.innerHTML = __ertr("<b>Book Reader</b> \u2014 \u0432\u0435\u0440\u0441\u0438\u044F {0}. \u0410\u0432\u0442\u043E\u0440: Elton Labs.", this.plugin.manifest.version) + '<br><a href="https://t.me/eltonlabs">t.me/eltonlabs</a>';
  }
